use xiom.io;

use xiom.string;
fn to_upper_char(c: Char) -> Char {
  if c >= 'a' && c <= 'z' {
    let offset = c as Int - 'a' as Int;
    return ('A' as Int + offset) as Char;
  };
  c
}

fn is_skip_word(word: Str) -> Bool {
  word == "and" || word == "of" || word == "the" || word == "for" || word == "a" || word == "in"
}

fn to_acronym(phrase: Str) -> Str {
  let mut acronym = "";
  let mut current = "";
  let mut i = 0;
  while i < phrase.len() {
    let c = phrase.get(i).unwrap();
    if c == ' ' {
      if current.len() > 0 && !is_skip_word(current) {
        acronym = string.str_concat(acronym, string.from_char(to_upper_char(current.get(0).unwrap())));
      };
      current = "";
    } else {
      current = string.str_concat(current, string.from_char(c));
    };
    i += 1;
  };
  if current.len() > 0 && !is_skip_word(current) {
    acronym = string.str_concat(acronym, string.from_char(to_upper_char(current.get(0).unwrap())));
  };
  acronym
}

fn main() -> Int {
  io.println(to_acronym("National Aeronautics and Space Administration"));
  io.println(to_acronym("Self Contained Underwater Breathing Apparatus"));
  return 0;
}
